settings.custom_css:
selector {
    background: rgba(255, 255, 255, 0.12) !important;
    backdrop-filter: blur(1px) !important;
    -webkit-backdrop-filter: blur(18px) !important;
    border: 1px solid rgba(255, 255, 255, 0.25) !important;
   
    
}

@media (max-width: 767px) {
  .elementor-element-0f0c707 {
    background: #000b2c; /* or your desired image/color */
  }

  .elementor-element-0f0c707 .elementor-background-video-container {
    display: none !important;
  }
}

selector .elementor-counter-number-suffix{
    font-size: 18px;
    display: inline-flex;
    align-items: center;
}

@media (max-width: 767px) {
  selector {
    background-image: linear-gradient(
      to bottom,
      #010D2B 0,
      transparent 100px
    );
    background-repeat: no-repeat;
  }
}

selector .elementor-counter-number-suffix{
    font-size: 18px;
    display: inline-flex;
    align-items: center;
}

@media (max-width: 767px) {
  selector::before {
    top: 0;
    height: 100px;
    background: linear-gradient(to bottom, #030F29, transparent) !important;
  }
}

@media (min-width: 768px) {

    selector .e-n-carousel.swiper {
        padding-top: 50px !important;
        padding-bottom: 50px !important;

        overflow: visible !important;

        /* Prevent responsive shrinking */
        width: 140vw !important;

        /* Keep centered */
        position: relative;
        left: 50%;
        transform: translateX(-50%);
    }

    /* Slides */
    selector .e-n-carousel .swiper-slide {
        transition: transform 0.4s ease-in-out, opacity 0.4s ease !important;
        transform: scale(0.90);
        opacity: 0.6;
        z-index: 1;
    }

    /* Active/next slide */
    selector .e-n-carousel .swiper-slide-next {
        transform: scale(1) !important;
        opacity: 1 !important;
        z-index: 10 !important;
        border: 1px solid #fbc91b;
        border-radius: 25px;
        box-shadow: 0 0 12px #fbc91b;
        min-height: 324px;
    }

    /* Allow overflow */
    selector .e-n-carousel .e-con-inner,
    selector .e-n-carousel .elementor-element {
        overflow: visible !important;
        padding: 12px;
    }
}


/* FIX FOR LARGE SCREENS */
@media (min-width: 1200px) {
    selector .e-n-carousel.swiper {
        width: 100% !important;
        left: 0 !important;
        transform: none !important;
        overflow: hidden !important;
    }
}


selector .elementor-image-box-content {
    position: relative;
    padding-right: 80px; /* space for SVG */
}

selector .elementor-image-box-content::after {
    content: "";
    position: absolute;
    right: 0;
    top: 50%;
    transform: translateY(-50%);

    width: 70px;
    height: 70px;

    background-image: url('/wp-content/uploads/2026/06/Quote.svg');
    background-repeat: no-repeat;
    background-size: contain;
    background-position: center;
}



@media (max-width: 768px) {


