        box-shadow: 0 0 12px #fbc91b;
    } }

/* Each item center */
.eael-horizontal-timeline .eael-horizontal-timeline-item {
    width: 100% !important;
    display: flex !important;
    justify-content: center !important;
    align-items: center !important;
    text-align: center !important;
}

/* Card width 350 and centered */
.eael-horizontal-timeline .eael-horizontal-timeline-item__card {
    width: 350px !important;
    max-width: 350px !important;
    margin-left: auto !important;
    margin-right: auto !important;
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
}

/* Remove card inner background */
.eael-horizontal-timeline .eael-horizontal-timeline-item__card-inner {
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
    padding: 0 !important;
}

/* Hide card arrows */
.eael-horizontal-timeline .eael-horizontal-timeline-item__card-arrow {
    display: none !important;
}

/* Center text */
.eael-horizontal-timeline .eael-horizontal-timeline-item__card-title,
.eael-horizontal-timeline .eael-horizontal-timeline-item__card-desc,
.eael-horizontal-timeline .eael-timeline-excerpt,
.eael-horizontal-timeline .eael-timeline-excerpt p {
    text-align: center !important;
}

/* Make icons also centered in same columns */
.eael-horizontal-timeline .eael-horizontal-timeline-list--middle .eael-horizontal-timeline-item {
    justify-content: center !important;
}/* 30px gap between cards and icons only - line/icons untouched */

/* Top cards move upward from icon */
.eael-horizontal-timeline .eael-horizontal-timeline-list--top .eael-horizontal-timeline-item__card {
    margin-bottom: 30px !important;
}

/* Bottom cards move downward from icon */
.eael-horizontal-timeline .eael-horizontal-timeline-list--bottom .eael-horizontal-timeline-item__card {
    margin-top: 30px !important;
}

selector img{
    max-width: 110px;
}

@media (max-width: 767px) {
selector img{
    max-width: 80px;
}
}
